index idx_budget_category_month :: CREATE UNIQUE INDEX idx_budget_category_month ON budgets (category_id, month_key) WHERE category_id IS NOT NULL
index idx_budget_overall_month :: CREATE UNIQUE INDEX idx_budget_overall_month ON budgets (month_key) WHERE category_id IS NULL
index idx_budgets_month :: CREATE INDEX idx_budgets_month ON budgets (month_key)
index idx_categories_type_sort :: CREATE INDEX idx_categories_type_sort ON categories (type, sort_order)
index idx_rules_due :: CREATE INDEX idx_rules_due ON recurring_rules (active, next_date)
index idx_tx_category_date :: CREATE INDEX idx_tx_category_date ON transactions (category_id, date)
index idx_tx_date :: CREATE INDEX idx_tx_date ON transactions (date)
index idx_tx_transfer_target :: CREATE INDEX idx_tx_transfer_target ON transactions (transfer_to_wallet_id)
index idx_tx_wallet_date :: CREATE INDEX idx_tx_wallet_date ON transactions (wallet_id, date)
index idx_wallets_sort :: CREATE INDEX idx_wallets_sort ON wallets (archived, sort_order)
table budgets :: CREATE TABLE "budgets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "category_id" INTEGER NULL REFERENCES categories (id) ON DELETE CASCADE, "month_key" TEXT NOT NULL, "amount_limit_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "notified_at_pct" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (amount_limit_minor > 0), CHECK (notified_at_pct BETWEEN 0 AND 100))
table categories :: CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "icon" TEXT NOT NULL DEFAULT 'tag', "color" INTEGER NOT NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0)
table exchange_rates :: CREATE TABLE "exchange_rates" ("base" TEXT NOT NULL, "quote" TEXT NOT NULL, "rate" REAL NOT NULL, "fetched_at" INTEGER NULL, "manual" INTEGER NOT NULL DEFAULT 1 CHECK ("manual" IN (0, 1)), PRIMARY KEY ("base", "quote"), CHECK (rate > 0), CHECK (base != quote))
table preferences :: CREATE TABLE "preferences" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"))
table recurring_rules :: CREATE TABLE "recurring_rules" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "wallet_id" INTEGER NOT NULL REFERENCES wallets (id) ON DELETE CASCADE, "category_id" INTEGER NULL REFERENCES categories (id) ON DELETE SET NULL, "type" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "note" TEXT NULL, "frequency" TEXT NOT NULL, "anchor_day" INTEGER NOT NULL DEFAULT 1, "next_date" TEXT NOT NULL, "end_date" TEXT NULL, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (amount_minor > 0), CHECK (type IN ('income', 'expense')), CHECK (anchor_day BETWEEN 1 AND 31))
table transactions :: CREATE TABLE "transactions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "wallet_id" INTEGER NOT NULL REFERENCES wallets (id) ON DELETE CASCADE, "category_id" INTEGER NULL REFERENCES categories (id) ON DELETE SET NULL, "type" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL, "note" TEXT NULL, "date" TEXT NOT NULL, "transfer_to_wallet_id" INTEGER NULL REFERENCES wallets (id) ON DELETE SET NULL, "recurring_rule_id" INTEGER NULL REFERENCES recurring_rules (id) ON DELETE SET NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (amount_minor > 0), CHECK ((type = 'transfer') = (transfer_to_wallet_id IS NOT NULL)), CHECK (transfer_to_wallet_id IS NULL OR transfer_to_wallet_id != wallet_id), CHECK (type != 'transfer' OR category_id IS NULL))
table wallets :: CREATE TABLE "wallets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'cash', "currency" TEXT NOT NULL, "initial_balance_minor" INTEGER NOT NULL DEFAULT 0, "color" INTEGER NOT NULL, "icon" TEXT NOT NULL DEFAULT 'wallet', "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)))
